# Generated by build.py from recipe.yml for recipe ftp-check-an-app-cleaned-up. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/work', 'site/leaky' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'scratch.txt'), "scratch`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/work/keep.txt'), "kept`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/leaky/keep.txt'), "kept`n")
[IO.File]::WriteAllText((Join-Path $PWD 'app.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# app.sh FOLDER-URL [leak]: the app under test. It uploads two temporary files to the folder URL (ending in /),`n# then deletes both, or only the first when given leak. A failed upload or delete is curl's exit code.`nurl=`$1`ncurl -sS -T scratch.txt `"`${url}a.tmp`" -T scratch.txt `"`${url}b.tmp`" || exit`nif [ `"`$2`" = leak ]; then`n  curl -sS -o /dev/null -l -Q `"-DELE a.tmp`" `"`$url`"`nelse`n  curl -sS -o /dev/null -l -Q `"-DELE a.tmp`" -Q `"-DELE b.tmp`" `"`$url`"`nfi`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# check.sh FOLDER-URL: lists the folder and fails, exit 1, naming what it finds if any .tmp file is left.`n# A listing that fails is curl's exit code, so a folder that cannot be listed never passes.`nnames=`$(curl -sS -l `"`$1`") || exit`nleft=`$(echo `"`$names`" | tr -d '\r' | grep '\.tmp`$' | tr '\n' ' ')`nif [ -n `"`$left`" ]; then echo `"leftover: `${left% }`"; exit 1; fi`necho clean`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--allow-uploads', '--list-directories', '--directory', 'site', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh app.sh ftp://127.0.0.1:8080/work/ && sh check.sh ftp://127.0.0.1:8080/work/ } finally { Stop-Process $server0 }
